Object.assign(en, {"rxn.fva": "Flux range (FVA)", "rxn.fvaTitle": "Minimum and maximum flux of this reaction among all solutions that reach the same objective value", "rxn.fvaBusy": "Computing the flux range…", "rxn.fvaSteady": "The flux range is computed in steady-state mode.", "rxn.fvaRange": "Flux range at the optimal objective: {lo} … {hi} mmol/gDW/h", "rxn.fvaFixed": "Fixed: every optimal solution needs exactly this flux.", "rxn.fvaZero": "Always zero: no optimal solution uses this reaction.", "rxn.fvaRequired": "Required: every optimal solution uses it, but the amount can vary.", "rxn.fvaFree": "Optional: optimal solutions exist with and without it; the flux shown is the one pFBA chose."});
Object.assign(es, {"rxn.fva": "Rango de flujo (FVA)", "rxn.fvaTitle": "Flujo mínimo y máximo de esta reacción entre todas las soluciones que alcanzan el mismo valor del objetivo", "rxn.fvaBusy": "Calculando el rango de flujo…", "rxn.fvaSteady": "El rango de flujo se calcula en modo estacionario.", "rxn.fvaRange": "Rango de flujo con el objetivo óptimo: {lo} … {hi} mmol/gDW/h", "rxn.fvaFixed": "Fijo: toda solución óptima necesita exactamente este flujo.", "rxn.fvaZero": "Siempre cero: ninguna solución óptima usa esta reacción.", "rxn.fvaRequired": "Necesaria: toda solución óptima la usa, pero la cantidad puede variar.", "rxn.fvaFree": "Opcional: hay soluciones óptimas con y sin ella; el flujo mostrado es el que eligió el pFBA."});
Object.assign(en, {"rxn.fvaLoop": "A limit of ±1000 is the model's default bound: a cycle of reactions can carry any amount of flux through it, so that end is not a real capacity."});
Object.assign(es, {"rxn.fvaLoop": "Un límite de ±1000 es la cota por defecto del modelo: un ciclo de reacciones puede llevar cualquier cantidad de flujo por ella, así que ese extremo no es una capacidad real."});
Object.assign(en, {"scr.button": "Screen essential genes", "scr.title": "Knock out, one by one, every detected gene whose reactions carry flux, and see which ones lower the objective (cell type and measured fluxes included; current knockouts ignored)", "scr.stop": "Stop the screen", "scr.needSteady": "The screen needs an optimal steady-state result: simulate first.", "scr.progress": "Screening {genes} genes: {done} of {total} linear programs…", "scr.summary": "{n} genes screened in {ctx} ({lp} linear programs, {s} s): {ess} essential, {red} lower the objective.", "scr.stopped": "Stopped before the end.", "scr.ess": "Essential (objective below 1 %)", "scr.red": "Lower the objective (1–95 %)", "scr.addTitle": "Add this knockout", "scr.relaxedNote": "* the measured fluxes had to be relaxed for this knockout."});
Object.assign(es, {"scr.button": "Cribar genes esenciales", "scr.title": "Anula uno a uno cada gen detectado cuyas reacciones llevan flujo y muestra cuáles bajan el objetivo (con tipo celular y flujos medidos; los knockouts actuales se ignoran)", "scr.stop": "Detener el cribado", "scr.needSteady": "El cribado necesita un resultado estacionario óptimo: simula primero.", "scr.progress": "Cribando {genes} genes: {done} de {total} programas lineales…", "scr.summary": "{n} genes cribados en {ctx} ({lp} programas lineales, {s} s): {ess} esenciales, {red} bajan el objetivo.", "scr.stopped": "Detenido antes del final.", "scr.ess": "Esenciales (objetivo por debajo del 1 %)", "scr.red": "Bajan el objetivo (1–95 %)", "scr.addTitle": "Añadir este knockout", "scr.relaxedNote": "* hubo que relajar los flujos medidos para este knockout."});
