Object.assign(en, {"flex.title": "Flux flexibility", "flex.fracTitle": "Objective held at this share of its optimum: 100 % = only optimal solutions; 99 or 95 % = nearly optimal ones too (closer to real cells)", "flex.btnTitle": "Flux range (FVA) of every reaction of this pathway: which fluxes the model really determines", "flex.button": "Compute for this pathway (FVA)", "flex.again": "Compute again", "flex.summary": "{p} % of the pathway's flux is determined (objective at {frac} % of its optimum).", "flex.c.fixed": "fixed", "flex.c.required": "required, amount varies", "flex.c.optional": "optional", "flex.c.loop": "reaches ±1000 (cycle)", "flex.c.zero": "always zero", "flex.progress": "Flux ranges: {i} of {n} reactions… ({s} s)", "flex.legend": "Rings: flux flexibility (objective at {frac} %)", "flex.altButton": "What can replace it?", "flex.altBusy": "Comparing the two ends of its range…", "flex.altTitle": "What changes with it", "flex.altUnit": "flux at its maximum minus at its minimum", "flex.altNote": "Between the solution where this reaction carries its least flux and the one where it carries most ({d} more), these reactions change most: they are the alternatives that take over its role."});
