Object.assign(en, {"trl.pick": "＋ Label a nutrient with a commercial tracer…", "trl.title": "Tracers sold by Cambridge Isotope Laboratories (catalogue numbers), grouped by what they are used for", "trl.cannot": "{n}: its metabolite or structure is not in this model.", "trl.applied": "{n} (CIL {item}) labelled in the medium.", "des.open": "Design a tracer experiment…", "des.openTitle": "Which tracer and which metabolites to measure to tell two hypotheses apart, or to see one flux", "des.title": "Design a tracer experiment", "des.intro": "For each tracer, the label is propagated on the fluxes of each situation and the isotopologue distributions of the metabolites you can measure are compared. The score is how far apart the situations are in units of your measurement error: above about 3 the difference should be visible.", "des.modeA": "Tell scenarios apart", "des.modeB": "Resolve a flux", "des.modeAHint": "Choose two or more situations: the current one and saved scenarios (Compare section), e.g. normoxia vs hypoxia, or control vs knockout.", "des.modeBHint": "Choose a reaction whose flux the model cannot pin down: the app compares the two ends of its flux range (FVA) with the objective at its optimum.", "des.rxnPh": "Search a reaction…", "des.rxnChosen": "Reaction: {n}", "des.tracers": "Candidate tracers", "des.measured": "Metabolites you can measure", "des.measuredHint": "Model names, separated by commas. Each one is measured as the whole cell: its compartments are mixed by how much each one is made.", "des.sd": "Measurement error", "des.sdUnit": "percentage points per isotopologue", "des.run": "Compare tracers", "des.needScen": "Save at least one scenario in Compare to use this mode.", "des.notInMedium": "Its nutrient is not in the current medium", "des.need2": "Choose at least two situations with an optimal steady-state result.", "des.needRxn": "Choose a reaction.", "des.fva": "Computing the two ends of its flux range…", "des.fixedRxn": "This reaction's flux is fixed at the optimum: there is nothing to resolve.", "des.atMin": "flux at its minimum ({x})", "des.atMax": "flux at its maximum ({x})", "des.needTracers": "Choose at least one tracer and one measurable metabolite.", "des.progress": "Simulating tracer × situation {i} of {n}… ({s} s)", "des.done": "Done in {s} s.", "des.unknown": "Not in the model: {list}.", "des.best": "Best choice:", "des.bestText": "{tr} (CIL {item}); measure {list} to tell «{a}» from «{b}».", "des.thTracer": "Tracer", "des.cellTitle": "Click to see the isotopologue distributions", "des.heatNote": "Each cell: separation of the situations' isotopologue distributions, in units of the measurement error ({sd} points). Tracers are sorted by the sum of their three best metabolites.", "trl.use.glycolysis": "Glucose carbon fate", "trl.use.ppp": "Glycolysis vs pentose phosphate", "trl.use.pc": "Pyruvate carboxylase vs PDH", "trl.use.tca": "TCA cycle and glutamine anaplerosis", "trl.use.reductive": "Reductive carboxylation", "trl.use.nitrogen": "Nitrogen fate", "trl.use.transamination": "Transamination", "trl.use.nucleotideN": "Nucleotide nitrogen", "trl.use.lactate": "Lactate and pyruvate as fuels", "trl.use.lipogenesis": "Acetyl-CoA sources, lipogenesis", "trl.use.fao": "Fatty acid oxidation", "trl.use.onecarbon": "Serine, glycine and one-carbon", "trl.use.gng": "Gluconeogenesis", "trl.use.ketone": "Ketone body oxidation", "trl.use.sugars": "Other sugars", "trl.use.carboxylation": "Carboxylation (CO2 fixation)", "trl.use.aminoacid": "Amino acid metabolism", "trl.use.bcaa": "Branched-chain amino acids", "trl.use.tcaint": "TCA intermediates", "trl.use.anaplerosis": "Anaplerosis via propionyl-CoA"});
Object.assign(es, {"trl.pick": "＋ Marcar un nutriente con un trazador comercial…", "trl.title": "Trazadores que vende Cambridge Isotope Laboratories (números de catálogo), agrupados por para qué se usan", "trl.cannot": "{n}: su metabolito o su estructura no están en este modelo.", "trl.applied": "{n} (CIL {item}) marcado en el medio.", "des.open": "Diseñar un experimento con trazadores…", "des.openTitle": "Qué trazador y qué metabolitos medir para distinguir dos hipótesis, o para ver un flujo", "des.title": "Diseñar un experimento con trazadores", "des.intro": "Para cada trazador, el marcaje se propaga sobre los flujos de cada situación y se comparan las distribuciones de isotopólogos de los metabolitos que puedes medir. La puntuación es cuánto se separan las situaciones en unidades de tu error de medida: por encima de 3, más o menos, la diferencia debería verse.", "des.modeA": "Distinguir escenarios", "des.modeB": "Resolver un flujo", "des.modeAHint": "Elige dos o más situaciones: la actual y escenarios guardados (sección Comparar), p. ej. normoxia frente a hipoxia, o control frente a knockout.", "des.modeBHint": "Elige una reacción cuyo flujo el modelo no fija: la app compara los dos extremos de su rango de flujo (FVA) con el objetivo en su óptimo.", "des.rxnPh": "Buscar una reacción…", "des.rxnChosen": "Reacción: {n}", "des.tracers": "Trazadores candidatos", "des.measured": "Metabolitos que puedes medir", "des.measuredHint": "Nombres del modelo, separados por comas. Cada uno se mide como célula entera: sus compartimentos se mezclan según cuánto se produce en cada uno.", "des.sd": "Error de medida", "des.sdUnit": "puntos porcentuales por isotopólogo", "des.run": "Comparar trazadores", "des.needScen": "Guarda al menos un escenario en Comparar para usar este modo.", "des.notInMedium": "Su nutriente no está en el medio actual", "des.need2": "Elige al menos dos situaciones con un resultado estacionario óptimo.", "des.needRxn": "Elige una reacción.", "des.fva": "Calculando los dos extremos de su rango de flujo…", "des.fixedRxn": "El flujo de esta reacción está fijo en el óptimo: no hay nada que resolver.", "des.atMin": "flujo en su mínimo ({x})", "des.atMax": "flujo en su máximo ({x})", "des.needTracers": "Elige al menos un trazador y un metabolito medible.", "des.progress": "Simulando trazador × situación {i} de {n}… ({s} s)", "des.done": "Hecho en {s} s.", "des.unknown": "No están en el modelo: {list}.", "des.best": "Mejor opción:", "des.bestText": "{tr} (CIL {item}); mide {list} para distinguir «{a}» de «{b}».", "des.thTracer": "Trazador", "des.cellTitle": "Haz clic para ver las distribuciones de isotopólogos", "des.heatNote": "Cada celda: separación de las distribuciones de isotopólogos de las situaciones, en unidades del error de medida ({sd} puntos). Los trazadores se ordenan por la suma de sus tres mejores metabolitos.", "trl.use.glycolysis": "Destino del carbono de la glucosa", "trl.use.ppp": "Glucólisis frente a pentosas fosfato", "trl.use.pc": "Piruvato carboxilasa frente a PDH", "trl.use.tca": "Ciclo de Krebs y anaplerosis por glutamina", "trl.use.reductive": "Carboxilación reductiva", "trl.use.nitrogen": "Destino del nitrógeno", "trl.use.transamination": "Transaminación", "trl.use.nucleotideN": "Nitrógeno de nucleótidos", "trl.use.lactate": "Lactato y piruvato como combustible", "trl.use.lipogenesis": "Fuentes de acetil-CoA, lipogénesis", "trl.use.fao": "Oxidación de ácidos grasos", "trl.use.onecarbon": "Serina, glicina y un carbono", "trl.use.gng": "Gluconeogénesis", "trl.use.ketone": "Oxidación de cuerpos cetónicos", "trl.use.sugars": "Otros azúcares", "trl.use.carboxylation": "Carboxilación (fijación de CO2)", "trl.use.aminoacid": "Metabolismo de aminoácidos", "trl.use.bcaa": "Aminoácidos ramificados", "trl.use.tcaint": "Intermediarios del ciclo de Krebs", "trl.use.anaplerosis": "Anaplerosis vía propionil-CoA"});
Object.assign(en, {"tour.tracers.t": "Commercial tracers", "tour.tracers.b": "40 tracers sold by Cambridge Isotope Laboratories, grouped by what they measure. One click labels that nutrient in the medium.", "tour.design.t": "Design a tracer experiment", "tour.design.b": "Which tracer and which metabolites to measure to tell two saved scenarios apart, or to see a flux the model cannot pin down.", "tour.map.b": "Line width and particle speed show flux. Double-click a group to open its pathway; click a node for its details. Grey dashed lines are reactions blocked by the cell type; in a pathway, \"Flux flexibility\" adds rings showing which fluxes are determined.", "tour.details.b": "A plain summary, what limits the objective, the most valuable metabolites, the ATP/NADH/NADPH balance and where the label goes. For a metabolite: its value and a phase plane; for a reaction: its flux range (FVA) and what can replace it."});
Object.assign(es, {"tour.tracers.t": "Trazadores comerciales", "tour.tracers.b": "40 trazadores que vende Cambridge Isotope Laboratories, agrupados por lo que miden. Un clic marca ese nutriente en el medio.", "tour.design.t": "Diseñar un experimento con trazadores", "tour.design.b": "Qué trazador y qué metabolitos medir para distinguir dos escenarios guardados, o para ver un flujo que el modelo no fija.", "tour.map.b": "El grosor de las líneas y la velocidad de las partículas muestran el flujo. Doble clic en un grupo abre su ruta; clic en un nodo muestra sus detalles. Las líneas grises discontinuas son reacciones bloqueadas por el tipo celular; en una ruta, «Flexibilidad de flujo» añade anillos que muestran qué flujos están determinados.", "tour.details.b": "Un resumen en frases, qué limita el objetivo, los metabolitos más valiosos, el balance de ATP/NADH/NADPH y adónde va la marca. Para un metabolito: su valor y un plano de fase; para una reacción: su rango de flujo (FVA) y qué puede sustituirla."});
