Object.assign(en, {"flex.cycles": "without cycles", "flex.cyclesTitle": "Cap the total flux at its pFBA minimum + 5 %, which removes internal loops (thermodynamically impossible cycles) that make ranges look wider than they are", "flex.noCycles": "Cycles excluded (total flux ≤ pFBA minimum + 5 %)."});
Object.assign(es, {"flex.cycles": "sin ciclos", "flex.cyclesTitle": "Limita el flujo total a su mínimo del pFBA + 5 %, lo que elimina los bucles internos (ciclos termodinámicamente imposibles) que hacen que los rangos parezcan más amplios de lo que son", "flex.noCycles": "Ciclos excluidos (flujo total ≤ mínimo del pFBA + 5 %)."});
